draw(C--B--A--F--D);

label("$A$", A, N);
label("$B$", B, SW);
label("$C$", C, NE);
label("$D$", D, W);
label("$E$", E, SW);
label("$F$", F, SE);
label("$38$", (A + D)/2, NW, red);
label("$77$", (B + D)/2, NW, red);
label("$115$", (A + C)/2, NE, red);
